import { z, type ZodTypeAny } from 'zod';
import { linkSchema, mediaUrlSchema, slugSchema } from './common.js';

/**
 * A single declarative field definition drives three things:
 *  - server-side validation (zod schema generated by `fieldsToZod`)
 *  - the admin form (the client renders a control per field type)
 *  - defaults for new records/sections
 */
export type FieldType =
  | 'text'
  | 'textarea'
  | 'richtext' // markdown, rendered safely (no raw HTML)
  | 'number'
  | 'money' // integer minor units, edited in major units
  | 'boolean'
  | 'select'
  | 'image'
  | 'images'
  | 'file' // document URL (PDF etc.) from the media library
  | 'link'
  | 'email'
  | 'slug'
  | 'date'
  | 'datetime'
  | 'list' // list of short strings
  | 'repeater' // list of objects described by `fields`
  | 'relation'; // id of another collection record

export interface FieldDef {
  name: string;
  label: string;
  type: FieldType;
  required?: boolean;
  help?: string;
  placeholder?: string;
  max?: number; // max length (strings) or max value (numbers)
  min?: number;
  maxItems?: number;
  options?: readonly { value: string; label: string }[];
  fields?: FieldDef[]; // repeater
  relation?: string; // relation: collection key
  group?: string; // admin form tab
  /** Hidden in the admin list/table but still editable */
  wide?: boolean;
}

function base(field: FieldDef): ZodTypeAny {
  switch (field.type) {
    case 'text':
    case 'textarea': {
      let s = z.string().trim().max(field.max ?? (field.type === 'text' ? 200 : 2000));
      if (field.required) s = s.min(1, `${field.label} is required`);
      return s;
    }
    case 'richtext': {
      let s = z.string().max(field.max ?? 50000);
      if (field.required) s = s.min(1, `${field.label} is required`);
      return s;
    }
    case 'email':
      return field.required ? z.string().trim().email() : z.union([z.string().trim().email(), z.literal('')]);
    case 'slug':
      return slugSchema;
    case 'number': {
      let n = z.number();
      if (field.min !== undefined) n = n.min(field.min);
      if (field.max !== undefined) n = n.max(field.max);
      return field.required ? n : n.nullable();
    }
    case 'money': {
      const n = z.number().int().min(0).max(field.max ?? 10_000_000_000);
      return field.required ? n : n.nullable();
    }
    case 'boolean':
      return z.boolean();
    case 'select': {
      const values = (field.options ?? []).map((o) => o.value);
      return z.enum(values as [string, ...string[]]);
    }
    case 'image':
    case 'file':
      return field.required ? mediaUrlSchema.refine((v) => v !== '', `${field.label} is required`) : mediaUrlSchema;
    case 'images':
      return z.array(mediaUrlSchema).max(field.maxItems ?? 40);
    case 'link':
      return field.required ? linkSchema.refine((v) => v !== '', `${field.label} is required`) : linkSchema;
    case 'date':
    case 'datetime': {
      const d = z.string().refine((v) => !Number.isNaN(Date.parse(v)), 'Invalid date');
      return field.required ? d : d.nullable();
    }
    case 'list':
      return z.array(z.string().trim().min(1).max(field.max ?? 300)).max(field.maxItems ?? 30);
    case 'repeater': {
      let arr = z.array(fieldsToZod(field.fields ?? [])).max(field.maxItems ?? 30);
      if (field.required) arr = arr.min(1, `Add at least one ${field.label.toLowerCase()}`);
      return arr;
    }
    case 'relation':
      return field.required ? z.string().min(1) : z.string().nullable();
  }
}

/** Builds a strict object schema from field definitions. Missing optional values fall back to empty defaults. */
export function fieldsToZod(fields: FieldDef[]) {
  const shape: Record<string, ZodTypeAny> = {};
  for (const f of fields) {
    const s = base(f);
    shape[f.name] = f.required ? s : s.optional().default(emptyValue(f) as never);
  }
  return z.object(shape);
}

export function emptyValue(field: FieldDef): unknown {
  switch (field.type) {
    case 'boolean':
      return false;
    case 'number':
    case 'money':
    case 'date':
    case 'datetime':
    case 'relation':
      return null;
    case 'images':
    case 'list':
    case 'repeater':
      return [];
    case 'select':
      return field.options?.[0]?.value ?? '';
    default:
      return '';
  }
}

export function defaultsFor(fields: FieldDef[]): Record<string, unknown> {
  return Object.fromEntries(fields.map((f) => [f.name, emptyValue(f)]));
}

export type ValidationIssue = { path: string; message: string };
export function zodIssues(error: z.ZodError): ValidationIssue[] {
  return error.issues.map((i) => ({ path: i.path.join('.'), message: i.message }));
}
